// frontend/src/App.js
import React, { useState } from "react";
import { sendRequest } from "./requests/requests";
import "./App.css";

function App() {
  const [imageFile, setImageFile] = useState(null);
  const [secondImage, setSecondImage] = useState(null);
  const [operation, setOperation] = useState("gray");
  const [params, setParams] = useState({});
  const [resultImage, setResultImage] = useState(null);
  const [preview, setPreview] = useState(null);
  const [previewSecond, setPreviewSecond] = useState(null);

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (!file || !file.type.startsWith("image/")) return;
    setImageFile(file);
    setPreview(URL.createObjectURL(file));
  };

  const handleSecondImageChange = (e) => {
    const file = e.target.files[0];
    if (!file || !file.type.startsWith("image/")) return;
    setSecondImage(file);
    setPreviewSecond(URL.createObjectURL(file));
  };

  const handleParamChange = (e) => {
    setParams({ ...params, [e.target.name]: e.target.value });
  };

  const handleSubmit = async () => {
    if (!imageFile) return alert("Lütfen birinci resmi seçiniz");
    const response = await sendRequest({ operation, imageFile, secondImageFile: secondImage, params });
    if (response) setResultImage(response.url);
  };

  const renderParams = () => {
    switch (operation) {
      case "binary":
        return <input name="threshold" type="number" defaultValue={127} onChange={handleParamChange} />;
      case "rotate":
        return <input name="angle" type="number" defaultValue={90} onChange={handleParamChange} />;
      case "zoom":
        return <input name="scale" type="number" step="0.1" defaultValue={1.5} onChange={handleParamChange} />;
      case "color":
        return <input name="mode" type="text" defaultValue="HSV" onChange={handleParamChange} />;
      case "contrast":
        return <input name="factor" type="number" step="0.1" defaultValue={0.5} onChange={handleParamChange} />;
      case "median":
        return <input name="kernel_size" type="number" defaultValue={3} onChange={handleParamChange} />;
      case "double_threshold":
        return (
          <>
            <input name="low_thresh" type="number" defaultValue={50} onChange={handleParamChange} />
            <input name="high_thresh" type="number" defaultValue={150} onChange={handleParamChange} />
          </>
        );
      case "edge":
        return (
          <>
            <input name="threshold1" type="number" defaultValue={100} onChange={handleParamChange} />
            <input name="threshold2" type="number" defaultValue={200} onChange={handleParamChange} />
          </>
        );
      case "noise":
        return <input name="amount" type="number" step="0.01" defaultValue={0.05} onChange={handleParamChange} />;
      case "denoise":
        return (
          <>
            <input name="filter_type" type="text" defaultValue="mean" onChange={handleParamChange} />
            <input name="kernel_size" type="number" defaultValue={3} onChange={handleParamChange} />
          </>
        );
      case "motion":
        return <input name="kernel_size" type="number" defaultValue={5} onChange={handleParamChange} />;
      case "morphology":
        return (
          <>
            <input name="morph_op" type="text" defaultValue="dilate" onChange={handleParamChange} />
            <input name="kernel_size" type="number" defaultValue={3} onChange={handleParamChange} />
          </>
        );
      case "arithmetic":
        return <input name="arithmetic_op" type="text" defaultValue="subtract" onChange={handleParamChange} />;
      default:
        return null;
    }
  };

  return (
    <div className="app-container">
      <h1>Görüntü İşleme Uygulaması</h1>
      <div className="controls">
        <select
          onChange={(e) => {
            setOperation(e.target.value);
            setParams({});
          }}
          value={operation}
        >
          <option value="gray">Gri Dönüşüm</option>
          <option value="binary">Binary Dönüşüm</option>
          <option value="rotate">Döndür</option>
          <option value="crop">Kırp</option>
          <option value="zoom">Yakınlaştır</option>
          <option value="color">Renk Uzayı</option>
          <option value="histogram">Histogram Germe</option>
          <option value="contrast">Kontrast Azaltma</option>
          <option value="median">Median Filtre</option>
          <option value="double_threshold">Çift Eşikleme</option>
          <option value="edge">Kenar Algılama</option>
          <option value="noise">Gürültü Ekle</option>
          <option value="denoise">Gürültü Temizle</option>
          <option value="motion">Motion Blur</option>
          <option value="morphology">Morfolojik İşlem</option>
          <option value="arithmetic">Aritmetik İşlem</option>
        </select>

        <input type="file" accept="image/*" onChange={handleImageChange} />

        {operation === "arithmetic" && (
          <input type="file" accept="image/*" onChange={handleSecondImageChange} />
        )}

        <div className="params">{renderParams()}</div>
        <button onClick={handleSubmit}>Uygula</button>
      </div>

      <div className="image-display">
        {preview && <img src={preview} alt="Orijinal" />}
        {previewSecond && <img src={previewSecond} alt="2. Görsel" />}
        {resultImage && <img src={resultImage} alt="Sonuç" />}
      </div>
    </div>
  );
}

export default App;
